before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <algorithm>
#include <iostream>
#include <vector>
int main() {
    std::vector<int> values{2, 4, 4};
    auto found = std::find(values.begin(), values.end(), 4);
    if (found != values.end()) std::cout << *found << '\n';
    else std::cout << "missing\n";
}

```

